function decode(link){if(!link.startsWith("saavn://"))throw new Error("Invalid Saavn link");return JSON.parse(decodeURIComponent(link.slice(8)))}exports.getMeta=async({link})=>{const s=decode(link),a=s.artist||"Unknown artist",al=s.album||"Saavn";return {title:s.name||"Unknown song",image:s.image||"",poster:s.image||"",synopsis:`${a}${al?` • ${al}`:""}`,type:"movie",tags:["music","saavn",a].filter(Boolean),linkList:[{title:"Audio",directLinks:[{title:s.name||"Song",link,type:"movie",image:s.image||""}]}]}};